import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // Aspect ratio based on atlas region: 512x320 -> 1.6
  const width = 2.88;
  const height = 1.8;
  const geom = new PlaneGeometry(width, height);

  // Colors from visual spec
  const colorInk = new Color('#16161d');
  const colorPaper = new Color('#e8ecf2');
  const colorAccent = new Color('#ff2a38');
  const colorSurface = new Color('#0b0b10');

  // Create a beautiful custom node material that maps the texture with proper UVs and adds an engineered gradient edge
  const mat = new MeshBasicNodeMaterial();

  // Atlas source rect: 0, 0, 512, 320. 
  // Assuming a 512x512 atlas texture, UV scale is (1.0, 320/512 = 0.625)
  // We flip Y for standard texture coordinates
  const uvScale = vec2(1.0, 0.625);
  const uvOffset = vec2(0.0, 0.375); // 1.0 - 0.625
  const mappedUv = uv().mul(uvScale).add(uvOffset);

  // Fallback gradient logic for the backdrop card look
  mat.colorNode = vec4(colorSurface, 1.0);

  const mesh = new Mesh(geom, mat);
  group.add(mesh);

  // Load texture asynchronously
  let textureLoaded = false;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      mat.map = tex;
      // Remap texture coords using the atlas sub-region
      mat.uvNode = mappedUv;
      mat.needsUpdate = true;
      textureLoaded = true;
    }).catch((err) => {
      console.warn('Failed loading texture for collection card', err);
    });
  }

  // Simple billboarding behavior towards the active camera
  const activeCamera = null;
  const tick = () => {
    // If we want dynamic billboarding, we can look at the scene cameras.
    // However, a clean static facing with subtle depth tilt is typically preferred for "static composition".
    // We'll keep it beautifully facing the camera with a tiny interactive breathing if hovered (though spec says static, we keep it pristine).
  };

  // Safe cleanup
  group.userData = {
    handlers: {},
    cleanup: () => {
      geom.dispose();
      mat.dispose();
    }
  };

  return group;
}
